export function getVocabularyBaseSize(): number {
  return POLISH_VOCABULARY_BASE.length;
}

const wordIndex = new Map<string, PolishWordEntry>();
POLISH_VOCABULARY_BASE.forEach((item) => {
  wordIndex.set(item.w.toLowerCase(), item);
});

export function findWordInBase(word: string): PolishWordEntry | undefined {
  return wordIndex.get(word.toLowerCase());
}

export function matchWordsInQuery(query: string): PolishWordEntry[] {
  const normalized = query.toLowerCase().trim();
  const tokens = normalized.split(/[\s,?.!;:—"'-]+/).filter(Boolean);

  const matched: PolishWordEntry[] = [];
  const seen = new Set<string>();

  for (const token of tokens) {
    const entry = wordIndex.get(token);
    if (entry && !seen.has(entry.w)) {
      matched.push(entry);
      seen.add(entry.w);
    }
  }

  // Sprawdzanie fraz wielowyrazowych
  for (const item of POLISH_VOCABULARY_BASE) {
    if (item.w.includes(' ') && normalized.includes(item.w) && !seen.has(item.w)) {
      matched.push(item);
      seen.add(item.w);
    }
  }

  return matched;
}
